source('scripts/load.R')
library(ggplot2)
stopifnot(isTRUE(jsonlite::read_json('results/wgs/wgs_validation.json')$passed))
tree<-ape::ladderize(ape::read.tree('results/wgs/phylogeny/observed.treefile'))
qc<-read.csv('results/wgs/wgs_qc.csv')
stopifnot(setequal(tree$tip.label,qc$sample[qc$callable_fraction>=.9]))
truth<-jsonlite::read_json('data/wgs_truth.json')
nt<-length(tree$tip.label);xx<-ape::node.depth.edgelength(tree);yy<-rep(NA_real_,length(xx));yy[seq_len(nt)]<-seq_len(nt)
ypos<-function(node){if(is.na(yy[node]))yy[node]<<-mean(vapply(tree$edge[tree$edge[,1]==node,2],ypos,numeric(1)));yy[node]};invisible(ypos(nt+1))
ed<-data.frame(x=xx[tree$edge[,1]],xend=xx[tree$edge[,2]],y=yy[tree$edge[,2]],yend=yy[tree$edge[,2]])
vertical<-do.call(rbind,lapply(unique(tree$edge[,1]),function(node){j<-tree$edge[tree$edge[,1]==node,2];data.frame(x=xx[node],y=min(yy[j]),yend=max(yy[j]))}))
tips<-data.frame(x=xx[seq_len(nt)],y=yy[seq_len(nt)],sample=tree$tip.label)
tips$group<-vapply(tips$sample,function(s)truth[[s]]$cluster,character(1))
nodes<-data.frame(x=xx[nt+seq_len(tree$Nnode)],y=yy[nt+seq_len(tree$Nnode)],support=tree$node.label)
nodes<-nodes[!is.na(nodes$support)&nodes$support!='',]
g<-ggplot()+geom_segment(data=ed,aes(x=x,xend=xend,y=y,yend=yend),colour='grey40')+geom_segment(data=vertical,aes(x=x,xend=x,y=y,yend=yend),colour='grey40')+geom_point(data=tips,aes(x,y,color=group),size=3)+geom_text(data=tips,aes(x=x+max(xx)*.025,y=y,label=sample),hjust=0,size=3.5)+geom_text(data=nodes,aes(x,y,label=support),vjust=-.8,size=2.8,colour='grey25')+scale_color_manual(values=c('Cluster A'='#2166ac','Cluster B'='#b35806','Close unlinked background'='grey50'))+scale_x_continuous(expand=expansion(mult=c(.02,.2)))+scale_y_continuous(breaks=NULL)+labs(title='Observed sequence phylogeny after quality filtering',subtitle='10 artificial core segments; GTR+G maximum likelihood; 1,000 ultrafast bootstraps',x='Expected substitutions per site',y=NULL,color=NULL,caption='Labels show ultrafast bootstrap percentages. Arbitrary display root; no transmission direction inferred.\nClose background relatives remain within genetic groups. Two low-depth controls were excluded by observed callability.')+theme_study()+theme(panel.grid=element_blank())
save_plot(g,'observed_phylogeny',11,7)
